import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Il circuito interruttore","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/p_matematica-per-informatica/pd/pdabc.md","filePath":"lezioni/p_matematica-per-informatica/pd/pdabc.md"}`),a={name:`lezioni/p_matematica-per-informatica/pd/pdabc.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="il-circuito-interruttore" tabindex="-1">Il circuito interruttore <a class="header-anchor" href="#il-circuito-interruttore" aria-label="Permalink to “Il circuito interruttore”">​</a></h1><p>Consideriamo un filo metallico con una lamina mobile tenuta attaccata al filo stesso mediante una molla, allora nel filo passa una corrente.</p><p>Se ora facciamo passare una corrente elettrica nel solenoide a destra, allora si attiva un campo magnetico che attira la lamina e quindi impedisce il passaggio di corrente nel filo.</p><p>Se poi smetto di erogare corrente al solenoide allora il campo magnetico sparisce e la molla fa tornare la lamina al suo posto e nel filo può ancora passare corrente.</p><p>Abbiamo quindi un circuito che serve da interruttore per far passare od interrompere il passaggio di corrente in un filo.</p><p>Basandoci su questo fatto in futuro indicheremo in questo modo un circuito in cui passi corrente (chiuso <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>) e in cui non passi la corrente (aperto <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>).</p>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};